package site.hsu.hub.recruitment.adapter.out.persistence;import jakarta.persistence.*;
@Entity@Table(name="question_options")public class QuestionOptionEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="question_id",nullable=false)private Long questionId;@Column(name="option_value",nullable=false,length=300)private String value;@Column(name="display_order",nullable=false)private int order;protected QuestionOptionEntity(){}public QuestionOptionEntity(Long q,String value,int order){questionId=q;this.value=value;this.order=order;}public Long questionId(){return questionId;}public String value(){return value;}public int order(){return order;}}
